import{_ as r,c as a,o as s,ag as t}from"./chunks/framework.Ci10AEOF.js";const m=JSON.parse('{"title":"Architecture","description":"How OIE is structured internally","frontmatter":{"title":"Architecture","description":"How OIE is structured internally"},"headers":[],"relativePath":"engine/architecture_overview.md","filePath":"engine/architecture_overview.md","lastUpdated":1793057853000}'),n={name:"engine/architecture_overview.md"},o={viewBox:"0 0 900 500",role:"img","aria-label":"A message enters the source connector, passes the preprocessor and the source filter and transformer, then each destination filter and transformer and its connector, whose response is handled by that destination response transformer, then the postprocessor, which produces the response returned to the source system.",style:{width:"100%",height:"auto","font-family":"system-ui,-apple-system,sans-serif"}};function i(h,e,l,c,d,p){return s(),a("div",null,[e[1]||(e[1]=t('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>The Open Integration Engine (OIE) is an open source integration engine for healthcare. It receives messages from one system, filters and transforms them under rules you define, and delivers them to other systems, in the formats those systems speak (HL7, X12, EDI, DICOM, XML, among others).</p><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h2><p>Filters, transformers, channel scripts and the JavaScript connectors all run JavaScript with access to the message, the maps and Java. Each part below has a usual job, and none is limited to it.</p><h3 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h3><p>A channel is an interface you configure to receive data from a source, take actions on that data (filter, transform, extract), and send it out to zero or more destinations.</p><p>Each channel has general properties including a unique ID, name, and description. Channels can also be configured with code template library links, library resources, deploy/start dependencies (to control deployment order), attachment handler settings, message storage and pruning settings, and custom metadata columns.</p><h3 id="data-types" tabindex="-1">Data types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data types&quot;">​</a></h3><p>A data type is the format of the message a channel is handling: HL7 v2.x, X12, DICOM, JSON, and so on. Using the <strong>inbound</strong> data type, the engine <strong>serializes</strong> the incoming message into an internal representation that filters and transformers can work with. Using the <strong>outbound</strong> data type, it <strong>deserializes</strong> that representation into the format that leaves the channel.</p><p>The internal representation varies by data type. For example, HL7 v2.x data is parsed into an <a href="./glossary.html#e4x">E4X</a> XML object, JSON data becomes a JavaScript Object, and Raw data stays a string, unparsed.</p><p>Supported data types include:</p><ul><li>Delimited Text</li><li>DICOM</li><li>EDI / X12</li><li>HL7 v2.x</li><li>HL7 v3.x</li><li>JSON</li><li>NCPDP Telecom</li><li>Raw</li><li>XML</li></ul><p>See <a href="./data_types_and_formats.html">Data Types and Formats</a> for details.</p><h3 id="connectors" tabindex="-1">Connectors <a class="header-anchor" href="#connectors" aria-label="Permalink to &quot;Connectors&quot;">​</a></h3><p>A channel consists of multiple <strong>connectors</strong>:</p><ul><li><strong>Source Connector</strong>. Gets data into the channel. Every channel has exactly one.</li><li><strong>Destination Connectors</strong>. Usually send the message somewhere, but need not: a Channel Writer left at its default channel, None, sends nothing, and a JavaScript Writer can run a script that only sets a map value. A channel is configured with at least one, and may have several. A given message may still reach none of them, if the source filter rejects it or destination set filtering removes them all. Each has an <strong>enabled</strong> flag and a <strong>wait for previous destination</strong> setting that decides its chain membership.</li></ul><p>For example, you may receive data over HTTP, then write it out to a file <strong>and</strong> insert pieces of it into a database.</p><p>A connector&#39;s type decides its configuration. A TCP Listener asks for a local address and port, an HTTP Listener for a base context path, a Database Reader for a query and a polling schedule.</p><p>Every source connector also carries a common block of <strong>source settings</strong>, though not all of them apply to every type:</p><ul><li>a <strong>source queue</strong>, which when on accepts the message and responds immediately rather than waiting for processing to finish. Turning it on enables a queue buffer size and changes what the response can be set to</li><li>a <strong>response selector</strong>, choosing which response goes back</li><li><strong>batch processing</strong>, splitting one inbound payload into several messages. Offered only by types that support batching</li><li><strong>max processing threads</strong>, controlling how many messages the channel processes at once</li></ul><p>An <strong>attachment</strong> is content stored with a message but apart from its body. The channel&#39;s <strong>attachment handler</strong> runs on the inbound message before the preprocessor and pulls attachments out of it, leaving a reference in their place. It can take the entire message, content matching one or more regular expressions, the pixel data of a DICOM message, or whatever a JavaScript script or a custom Java class extracts. A script can also create, read or update attachments at other stages with <code>addAttachment</code>, <code>getAttachments</code> and <code>updateAttachment</code>. By default a destination puts the content back in place of the reference before it sends. See <a href="./message_lifecycle.html#attachments">Message Lifecycle and Storage</a>.</p><p>See <a href="./channels.html">Channels</a>, and <a href="./connector_reference_sources.html">Source Connectors</a> and <a href="./connector_reference_destinations.html">Destination Connectors</a> for what each type exposes.</p><h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><p>A filter decides whether a message should proceed to the next step or not. A filter returns <strong>true</strong> (accepted) or <strong>false</strong> (filtered). Filters are comprised of multiple <strong>rules</strong>, joined by <strong>AND</strong> or <strong>OR</strong> operators.</p><ul><li>If the source connector filters out a message, it will not be processed by any destination connectors.</li><li>If a destination connector filters out a message, other destinations may still process it.</li></ul><h3 id="transformers" tabindex="-1">Transformers <a class="header-anchor" href="#transformers" aria-label="Permalink to &quot;Transformers&quot;">​</a></h3><p>A transformer modifies a message, converts it from one format to another, and extracts pieces for later use. A transformer has an <strong>inbound data type</strong> and an <strong>outbound data type</strong> (e.g., HL7 v2.x to XML). Transformers are comprised of multiple <strong>steps</strong>, each of which modifies or extracts data.</p><p>See <a href="./filters_and_transformers.html">Filters and Transformers</a> for details.</p><h3 id="response-transformers" tabindex="-1">Response transformers <a class="header-anchor" href="#response-transformers" aria-label="Permalink to &quot;Response transformers&quot;">​</a></h3><p>Every destination can have a <strong>response transformer</strong>, which runs on what the destination got back. Its steps can do anything a transformer step can, and it can also set the status the message ends up with. It is the only transformer that runs after a connector rather than before one. Unless its inbound data type is Raw, it runs only when a response came back, so most failed sends skip it; see <a href="./filters_and_transformers.html#response-transformers">Response transformers</a>.</p><h3 id="channel-scripts" tabindex="-1">Channel scripts <a class="header-anchor" href="#channel-scripts" aria-label="Permalink to &quot;Channel scripts&quot;">​</a></h3><p>Four special scripts are associated with each channel:</p><ul><li><strong>Deploy Script</strong>. Runs once right before a channel is deployed.</li><li><strong>Preprocessor Script</strong>. Runs once for every message, after the attachment handler has optionally extracted data, but before the source filter/transformer. It can modify the incoming message.</li><li><strong>Post Processor Script</strong>. Runs once for every message, after the source connector and all destinations have completed (excluding asynchronous processes like the destination queue). Has access to responses from all executed destinations and can return a custom response for the source connector to use.</li><li><strong>Undeploy Script</strong>. Runs once after the channel has been stopped and its connectors undeployed.</li></ul><p>Global scripts of the same four kinds run around these for every channel. See <a href="./global_scripts.html#execution-order">Global Scripts</a>.</p><h3 id="how-a-message-moves" tabindex="-1">How a message moves <a class="header-anchor" href="#how-a-message-moves" aria-label="Permalink to &quot;How a message moves&quot;">​</a></h3>',35)),(s(),a("svg",o,e[0]||(e[0]=[t('<defs><marker id="cf-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="var(--vp-c-text-3)"></path></marker></defs><rect x="170" y="16" width="520" height="468" rx="10" fill="var(--vp-c-bg-soft)" stroke="var(--vp-c-divider)"></rect><text x="186" y="40" font-size="13" font-weight="600" fill="var(--vp-c-text-2)">OIE Channel</text><g fill="none" stroke="var(--vp-c-text-3)" stroke-width="1.5"><path d="M593,100 V122 H250 V300"></path><path d="M666,163 H706 V238"></path><path d="M666,300 H706 V238"></path></g><g fill="none" stroke="var(--vp-c-text-3)" stroke-width="1.5" marker-end="url(#cf-arrow)"><path d="M126,79 H184"></path><path d="M338,79 H352"></path><path d="M490,79 H504"></path><path d="M250,163 H258"></path><path d="M480,163 H492"></path><path d="M581,184 V192"></path><path d="M250,300 H258"></path><path d="M480,300 H492"></path><path d="M581,321 V329"></path><path d="M706,238 H742"></path><path d="M581,375 V433 H484"></path></g><path d="M262,433 H200 V466 H67 V111" fill="none" stroke="var(--vp-c-text-3)" stroke-width="1.5" stroke-dasharray="5 4" marker-end="url(#cf-arrow)"></path><text x="122" y="458" font-size="11" fill="var(--vp-c-text-2)">response</text><g fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"><rect x="8" y="51" width="118" height="56" rx="6"></rect><rect x="746" y="210" width="136" height="56" rx="6"></rect><rect x="188" y="58" width="150" height="42" rx="5"></rect><rect x="356" y="58" width="134" height="42" rx="5"></rect><rect x="508" y="58" width="170" height="42" rx="5"></rect><rect x="262" y="142" width="218" height="42" rx="5"></rect><rect x="496" y="142" width="170" height="42" rx="5"></rect><rect x="496" y="196" width="170" height="42" rx="5"></rect><rect x="262" y="279" width="218" height="42" rx="5"></rect><rect x="496" y="279" width="170" height="42" rx="5"></rect><rect x="496" y="333" width="170" height="42" rx="5"></rect><rect x="262" y="412" width="218" height="42" rx="5"></rect></g><g font-size="12" fill="var(--vp-c-text-1)" text-anchor="middle" dominant-baseline="central"><text x="67" y="70">Source</text><text x="67" y="88">System</text><text x="814" y="229">Destination</text><text x="814" y="247">System(s)</text><text x="263" y="79">Source Connector</text><text x="423" y="79">Preprocessor</text><text x="593" y="79">Source Filter/Transformer</text><text x="371" y="163">Destination 1 Filter/Transformer</text><text x="581" y="163">Connector 1</text><text x="581" y="217">Response Transformer 1</text><text x="371" y="300">Destination 2 Filter/Transformer</text><text x="581" y="300">Connector 2</text><text x="581" y="354">Response Transformer 2</text><text x="371" y="433">Postprocessor</text></g>',9)]))),e[2]||(e[2]=t('<p>Destination 2 follows destination 1 in the diagram because it waits for the previous destination, which is the default. With that setting off, each destination starts a chain of its own and the chains run concurrently.</p><p>Neither end of that diagram has to be outside OIE. A Channel Reader source receives from Channel Writers on other channels, a Channel Writer destination hands the message to another channel on the same engine, and a script can dispatch to one through <code>router</code>.</p><p>A message moves through these steps:</p><ol><li>The <strong>source connector</strong> receives the message.</li><li>The <strong>attachment handler</strong>, if one is configured, pulls content out of the message and leaves a reference in its place.</li><li>The <strong>preprocessor script</strong> can modify the raw message before anything parses it.</li><li>The <strong>source filter</strong> decides whether the message goes on, and the <strong>source transformer</strong> converts and extracts from it. A message filtered here reaches no destination.</li><li>For each destination: its <strong>filter and transformer</strong> run, then its <strong>connector</strong> runs, which usually sends the message, either now or later from its queue.</li><li>That destination&#39;s <strong>response transformer</strong> handles whatever comes back.</li><li>The <strong>postprocessor script</strong> runs once every destination has finished, and can build the response itself.</li><li>If something is waiting on the other end, the response goes back to it. A listener source such as an HTTP, TCP, or Web Service Listener returns it to the caller. A polling source such as a Database Reader or File Reader has no caller, so the response is selected and stored on the message but sent nowhere.</li></ol><p>Four pages explain the mechanisms behind those steps:</p><ul><li><a href="./message_lifecycle.html">Message Lifecycle and Storage</a>, the processing path, statuses, content types, and what each storage mode keeps</li><li><a href="./queueing.html">Queueing</a>, the source queue and destination queues</li><li><a href="./threading_and_ordering.html">Threading and Ordering</a>, which thread does the work, chains, and response selection</li><li><a href="./channel_state.html">Deploy, Start, and Channel State</a>, what deploy does and what each state means</li></ul><p>The <a href="./glossary.html">Glossary</a> collects the terms these pages use.</p><h2 id="administration-interfaces" tabindex="-1">Administration interfaces <a class="header-anchor" href="#administration-interfaces" aria-label="Permalink to &quot;Administration interfaces&quot;">​</a></h2><ul><li><strong>Administrator</strong>. A Java Swing desktop client for managing channels, viewing messages, configuring settings, and monitoring the system. Connects to the server over HTTPS using a RESTful API. Requires a compatible launcher; see <a href="./desktop_administrator.html">Desktop Administrator</a> for the available options.</li><li><strong><a href="./web_administrator.html">Web Administrator</a></strong>. A browser-based administrator. It is a separate application that uses the same REST API as the desktop client.</li><li><strong>Command Line Interface (CLI)</strong>. A terminal-based client for scripting and headless administration. Uses the same REST API as the Administrator.</li></ul><h2 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;Extensions&quot;">​</a></h2><p>OIE uses a plugin architecture where connectors, data types, and other features are loaded as extensions. Extension types include:</p><ul><li><strong>Connectors</strong>. Source and destination communication protocols</li><li><strong>Data Type Plugins</strong>. Message formats and the settings the engine uses to serialize and deserialize them</li><li><strong>Server Plugins</strong>. Background services and event handlers</li><li><strong>Transmission Mode Providers</strong>. Frame-level protocol handling (e.g., <a href="./glossary.html#mllp">MLLP</a>)</li></ul><p>Extensions are loaded from the extensions directory when the engine starts. An extension can ship a desktop UI, a web UI, or both; the web administrator serves the web side. Open source extensions are available beyond those bundled with the engine. See the <a href="./plugins.html">Plugin Guide</a>, and <a href="https://openintegrationengine.org/plugins/" target="_blank" rel="noreferrer">openintegrationengine.org/plugins</a> for the community catalog.</p>',13))])}const u=r(n,[["render",i]]);export{m as __pageData,u as default};
